const axios = require("axios");
const cheerio = require("cheerio");

let pageText = "";
let viewportIndex = 0;
let lastSearch = null;
const PAGE_SIZE = 1000;

function getViewport() {
  return pageText.slice(viewportIndex, viewportIndex + PAGE_SIZE);
}

async function code_search({ query, year_filter = null }) {
  let result = `Search results for "${query}"`;
  if (year_filter) result += ` filtered to ${year_filter}`;
  return result;
}

async function open_page({ url }) {
  const res = await axios.get(url);
  const $ = cheerio.load(res.data);
  pageText = $("body").text();
  viewportIndex = 0;
  return getViewport();
}

function page_up() {
  viewportIndex = Math.max(0, viewportIndex - PAGE_SIZE);
  return getViewport();
}

function page_down() {
  viewportIndex = Math.min(pageText.length, viewportIndex + PAGE_SIZE);
  return getViewport();
}

function find_on_page({ search_string }) {
  const regex = new RegExp(search_string.replace(/\*/g, ".*"), "i");
  const match = pageText.search(regex);
  if (match === -1) return "No match found";
  viewportIndex = match;
  lastSearch = regex;
  return getViewport();
}

function find_next() {
  if (!lastSearch) return "No previous search";
  const regex = new RegExp(lastSearch.source, "ig");
  regex.lastIndex = viewportIndex + 1;
  const match = regex.exec(pageText);
  if (!match) return "No further matches";
  viewportIndex = match.index;
  return getViewport();
}

async function archive_lookup({ url, date = null }) {
  let api = `https://archive.org/wayback/available?url=${encodeURIComponent(url)}`;
  if (date) api += `&timestamp=${date}`;
  const res = await axios.get(api);
  const snap = res.data?.archived_snapshots?.closest;
  return snap ? snap.url : "No archived snapshot found";
}

module.exports = {
  code_search,
  open_page,
  page_up,
  page_down,
  find_on_page,
  find_next,
  archive_lookup
};

<end_plan>
